package com.ejemplo.alquileres.ui;
import com.ejemplo.alquileres.model.SemaforoMorosidad; import javafx.scene.control.Label;
/** Pastilla común de morosidad. */
public final class Semaforo {private Semaforo(){} public static Label crear(SemaforoMorosidad s){Label l=new Label(texto(s));l.getStyleClass().addAll("chip","semaforo",estilo(s));return l;}public static String texto(SemaforoMorosidad s){return switch(s==null?SemaforoMorosidad.AL_DIA:s){case AL_DIA->"Al día";case ATRASO_LEVE->"Atraso leve";case MOROSO->"Moroso";};}public static String estilo(SemaforoMorosidad s){return switch(s==null?SemaforoMorosidad.AL_DIA:s){case AL_DIA->"exito";case ATRASO_LEVE->"advertencia";case MOROSO->"peligro";};}}